      "scholarshipType": "Amount",
      "scholarshipMetaData": [
        {
          "description": "Offered through University of Auckland International College (UP Education). Eligibility: top Foundation students progressing to a University of Auckland bachelor's degree."
        },
        {
          "description": "More information: https://www.auckland.ac.nz/assets/study/scholarships-and-funding/find-a-scholarship-or-award/regulations/university-of-auckland-foundation-pathway-high-achiever-award.pdf"
        }
      ]
    },
    {
      "scholarshipName": "",
      "scholarshipAmount": "25000",
      "scholarshipType": "Percentage",
      "scholarshipMetaData": [
        {
          "description": "A tuition fees credit of up to 25% of the recipient's tuition fees for the first two semesters of their master's degree."
        },
        {
          "description": "Eligibility: applicant must be an international student."
        },
        {
          "description": "Eligibility: applicant must have received a conditional or unconditional offer of admission to an eligible master's programme at the University of Auckland."
        },
        {
          "description": "Eligibility: applicant must have an Admissions GPE of at least 7.0."
        },
        {
          "description": "More information: https://www.auckland.ac.nz/assets/study/scholarships-and-funding/find-a-scholarship-or-award/regulations/university-of-auckland-international-student-excellence-scholarship.pdf"
        }
      ]
    },
    {
      "scholarshipName": "",
      "scholarshipAmount": "35468",
      "scholarshipType": "Amount",
      "scholarshipMetaData": [
        {
          "description": "Supports excellent domestic and international doctoral candidates whose research aligns with the strategic objectives of the University of Auckland."
        },
        {
          "description": "Applicable programmes: PhD, DMedSc, DClinPsy, DocFA, EdD and DHSc."
        },
        {
          "description": "Term: up to 42 months of full-time equivalent enrolment."
        },
        {
          "description": "Application: no separate application is required. Applicants indicate in their doctoral application that they wish to be considered."
        },
        {
          "description": "Selection: based on alignment with the strategic objectives of the University and the relevant faculty or research institute."
        },
        {
          "description": "Eligibility: applicant must be a domestic student, or an international student who is eligible to pay domestic fees for the doctoral programme."
        },
        {
          "description": "Eligibility: applicant must not already hold a doctorate or have previously received payment for a University of Auckland Doctoral Scholarship."
        },
        {
          "description": "Eligibility: applicant must not be enrolled in a doctoral programme, except for approved transfers."
        },
        {
          "description": "More information: https://www.auckland.ac.nz/assets/study/scholarships-and-funding/find-a-scholarship-or-award/regulations/university-of-auckland-doctoral-scholarship.pdf"
        }
      ]
    }
  ]
